journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_name(value):
    return isinstance(value, str) and value != ""


def _read_ids(value, code):
    if not isinstance(value, list):
        raise JournalError(code)
    ids = []
    for name in value:
        if not _is_name(name):
            raise JournalError(code)
        ids.append(name)
    return ids


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if (not isinstance(row, dict)
                or not _is_name(row.get("id"))
                or not _is_name(row.get("component"))
                or not isinstance(row.get("units"), int)
                or isinstance(row.get("units"), bool)
                or row["units"] < 1):
            raise JournalError("invalid-change")
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_ids(row.get("depends_on", []), "invalid-change"),
        })
    return changes


def collapse(changes):
    """Collapse identical duplicate records; reject conflicting IDs."""
    records = {}
    for row in changes:
        signature = (row["component"], row["units"], frozenset(row["depends_on"]))
        if row["id"] in records:
            if records[row["id"]]["signature"] != signature:
                raise JournalError("conflicting-change")
            continue
        records[row["id"]] = {
            "signature": signature,
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": sorted(signature[2]),
        }
    for record in records.values():
        del record["signature"]
    return records


def read_applied(names, known):
    """Validate the persisted journal supplied by the caller."""
    applied = set()
    for name in _read_ids(names, "invalid-change"):
        if name not in known:
            raise JournalError("unknown-dependency")
        applied.add(name)
    return applied


def read_journal(request):
    """Validate identity and replay state, returning records and applied IDs."""
    changes = read_changes(request.get("changes"))
    records = collapse(changes)

    dependencies = {}
    for name, record in records.items():
        for target in record["depends_on"]:
            if target not in records:
                raise JournalError("unknown-dependency")
        dependencies[name] = set(record["depends_on"])

    applied = read_applied(request.get("applied", []), records)
    return records, dependencies, applied

