        if row["id"] in records:
            if records[row["id"]]["signature"] != signature:
                raise JournalError("conflicting-change")
            continue
        records[row["id"]] = {
            "signature": signature,
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": sorted(signature[2]),
        }
    for record in records.values():
        del record["signature"]
    return records


def read_retain(names, applied):
    """Validate the G2 staging rollback retain list: IDs already applied to keep."""
    retained = set()
    for name in _read_ids(names, "invalid-retain"):
        if name not in applied:
            raise JournalError("invalid-retain")
        retained.add(name)
    return retained


def read_applied(names, known):
    """Validate the persisted journal supplied by the caller."""
    applied = set()
    for name in _read_ids(names, "invalid-change"):
        if name not in known:
            raise JournalError("unknown-dependency")
        applied.add(name)
    return applied


def read_journal(request):
    """Validate identity and replay state, returning records and applied IDs."""
    changes = read_changes(request.get("changes"))
    records = collapse(changes)

    dependencies = {}
    for name, record in records.items():
        for target in record["depends_on"]:
            if target not in records:
                raise JournalError("unknown-dependency")
        dependencies[name] = set(record["depends_on"])

    applied = read_applied(request.get("applied", []), records)
    return records, dependencies, applied

