"""Compose policy and journal data into a plan."""
from heapq import heapify, heappop, heappush

from journal import JournalError, read_journal, read_retain
from policy import PolicyError, assert_supported, is_frozen, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(dependencies):
    """Kahn's algorithm, taking the lexicographically smallest eligible ID."""
    pending = {name: set(dependencies[name]) for name in dependencies}
    waited_on = {name: [] for name in dependencies}
    for name, targets in pending.items():
        for target in targets:
            waited_on[target].append(name)
    ready = [name for name, targets in pending.items() if not targets]
    heapify(ready)
    order = []
    while ready:
        name = heappop(ready)
        order.append(name)
        for child in waited_on[name]:
            pending[child].discard(name)
            if not pending[child]:
                heappush(ready, child)
    if len(order) != len(pending):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(retained, dependencies, applied):
    """Expand retained IDs with the applied transitive dependencies they require.

    The result is the set of applied changes that must survive a rollback.
    """
    keep = set()
    stack = sorted(retained)
    while stack:
        name = stack.pop()
        if name in keep:
            continue
        keep.add(name)
        for target in dependencies[name]:
            if target in applied and target not in keep:
                stack.append(target)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # G2: a staging-only release refuses production before touching the graph.
        assert_supported(request)
        if is_frozen(request["environment"]):
            return failure("production-frozen")
        budget = limit_for(request)
        records, dependencies, applied = read_journal(request)
        order = topological_order(dependencies)
        retained = set()
        if request["action"] == "rollback":
            retained = read_retain(request.get("retain", []), applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if request["action"] == "rollback":
        keep = retained_closure(retained, dependencies, applied)
        actions = [name for name in reversed(order) if name in applied and name not in keep]
        return {
            "status": "ok",
            "actions": actions,
            "units": sum(records[name]["units"] for name in actions),
        }

    actions = [name for name in order if name not in applied]
    units = sum(records[name]["units"] for name in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

