"""Validate release policy before computing actions."""

ENVIRONMENTS = frozenset({"staging", "production"})
ACTIONS = frozenset({"plan", "rollback"})

# G2: this release is staging-only. Both plan and rollback are frozen in production.
FROZEN_ENVIRONMENTS = frozenset({"production"})
# G2: a staging plan may never spend more than this many units, whatever was requested.
STAGING_PLAN_CAP = 3


class PolicyError(ValueError):
    pass


def _known(value, allowed):
    """Membership test that tolerates unhashable JSON values such as lists."""
    return isinstance(value, str) and value in allowed


def is_frozen(environment):
    """True when the environment accepts no action at all."""
    return _known(environment, FROZEN_ENVIRONMENTS)


def assert_supported(request):
    """Check only what is needed to decide whether the request is allowed at all.

    Deliberately ignores `budget`, `changes` and `applied`, so a frozen
    environment is reported before any graph or change validation.
    """
    if not _known(request.get("environment"), ENVIRONMENTS):
        raise PolicyError("invalid-environment")
    action = request.get("action")
    if not isinstance(action, str) or action not in ACTIONS:
        raise PolicyError("unsupported-action")


def limit_for(request):
    """Return the effective budget for an already validated request."""
    if is_frozen(request["environment"]):
        raise PolicyError("production-frozen")
    action = request.get("action")
    if not isinstance(action, str) or action not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if not isinstance(budget, int) or isinstance(budget, bool):
        raise PolicyError("invalid-budget")
    if budget < 0:
        raise PolicyError("invalid-budget")
    if action == "plan":
        return min(budget, STAGING_PLAN_CAP)
    return budget

