"""Normalize release records at the input boundary.

Handles validation, identity and replay: parsing `changes` and the persisted
`applied` journal into a deduplicated graph, then preparing the full graph for
topological ordering. The planner consumes the prepared graph.
"""
import heapq


class JournalError(ValueError):
    pass


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change_id = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not isinstance(change_id, str) or not change_id
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        deps = row.get("depends_on")
        if deps is None:
            deps = []
        if not isinstance(deps, list):
            raise JournalError("invalid-change")
        for dep in deps:
            if not isinstance(dep, str) or not dep:
                raise JournalError("invalid-change")
        changes.append({
            "id": change_id,
            "component": component,
            "units": units,
            "depends_on": sorted(set(deps)),
        })
    return changes


def read_applied(records):
    """Parse the persisted journal into a set of applied change IDs."""
    if records is None:
        return set()
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    applied = set()
    for entry in records:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-change")
        applied.add(entry)
    return applied


def _collapse(rows):
    by_id = {}
    for row in rows:
        prior = by_id.get(row["id"])
        if prior is None:
            by_id[row["id"]] = row
        elif (prior["component"] != row["component"]
              or prior["units"] != row["units"]
              or prior["depends_on"] != row["depends_on"]):
            raise JournalError("conflicting-change")
    return by_id


def _check_targets(nodes, applied):
    for row in nodes.values():
        for dep in row["depends_on"]:
            if dep not in nodes:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in nodes:
            raise JournalError("unknown-dependency")


def order_all(nodes):
    """Full deterministic topological order: lexicographic ID tie-breaking."""
    remaining = {change_id: set(row["depends_on"]) for change_id, row in nodes.items()}
    dependents = {change_id: [] for change_id in nodes}
    for change_id, deps in remaining.items():
        for dep in deps:
            dependents[dep].append(change_id)
    ready = [change_id for change_id, deps in remaining.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for child in dependents[current]:
            remaining[child].discard(current)
            if not remaining[child]:
                heapq.heappush(ready, child)
    if len(order) != len(nodes):
        raise JournalError("dependency-cycle")
    return order


def read_graph(records, applied_records=None):
    """Return (nodes_by_id, applied_set, full_order).

    Duplicates collapse, conflicting duplicates fail, and every graph or journal
    reference must resolve before any ordering work happens.
    """
    rows = read_changes(records)
    applied = read_applied(applied_records)
    nodes = _collapse(rows)
    _check_targets(nodes, applied)
    order = order_all(nodes)
    return nodes, applied, order

