"""Compose policy and journal data into a plan.

Handles graph/order results and assembles responses. Every failure path returns
the exact error envelope with no partial actions.
"""
from journal import JournalError, read_graph
from policy import PolicyError, budget_caps, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, nodes):
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(nodes[change_id]["units"] for change_id in actions),
    }


def select(action, nodes, applied, order):
    if action == "rollback":
        return [change_id for change_id in reversed(order) if change_id in applied]
    return [change_id for change_id in order if change_id not in applied]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        nodes, applied, order = read_graph(request.get("changes"), request.get("applied"))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    actions = select(action, nodes, applied, order)
    units = sum(nodes[change_id]["units"] for change_id in actions)
    if budget_caps(action) and units > budget:
        return failure("budget-exceeded")
    return success(actions, nodes)

