"""Compose policy and journal data into a plan.

Handles graph/order results and assembles responses. Every failure path returns
the exact error envelope with no partial actions.
"""
from journal import JournalError, read_graph, read_retain
from policy import PolicyError, budget_caps, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, nodes):
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(nodes[change_id]["units"] for change_id in actions),
    }


def protected(keep, nodes):
    """Retained IDs plus their transitive dependencies, `keep` included."""
    guarded = set()
    pending = list(keep)
    while pending:
        change_id = pending.pop()
        if change_id in guarded:
            continue
        guarded.add(change_id)
        pending.extend(nodes[change_id]["depends_on"])
    return guarded


def select(action, nodes, applied, order, keep=frozenset()):
    if action == "rollback":
        guarded = protected(keep, nodes)
        return [change_id for change_id in reversed(order)
                if change_id in applied and change_id not in guarded]
    return [change_id for change_id in order if change_id not in applied]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
    except PolicyError as exc:
        return failure(str(exc))
    try:
        nodes, applied, order = read_graph(request.get("changes"), request.get("applied"))
        keep = read_retain(request.get("retain"), applied) if action == "rollback" else frozenset()
    except JournalError as exc:
        return failure(str(exc))
    actions = select(action, nodes, applied, order, keep)
    units = sum(nodes[change_id]["units"] for change_id in actions)
    if budget_caps(action) and units > budget:
        return failure("budget-exceeded")
    return success(actions, nodes)

policy.py.text:
"""Validate release policy before computing actions.

Handles environment and budget: which environments exist, which actions each
environment supports, and how the budget is interpreted for each action.

The current goal (G2) is staging-only. Production is frozen before any graph or
change validation, so a frozen request always reports `production-frozen` even
when the rest of the request is malformed.
"""

ENVIRONMENTS = {"staging", "production"}
ACTIONS = {"plan", "rollback"}
CAPPED_ACTIONS = {"plan"}
FROZEN_ENVIRONMENTS = {"production"}
# G2: staging plans are capped even when the request permits more.
STAGING_PLAN_CAP = 3


class PolicyError(ValueError):
    pass


def budget_caps(action):
    """Whether the budget limits the units of emitted actions."""
    return action in CAPPED_ACTIONS


def limit_for(request):
    """Validate policy fields and return (action, effective_budget)."""
    environment = request.get("environment")
    if environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if environment in FROZEN_ENVIRONMENTS:
        raise PolicyError("production-frozen")
    action = request.get("action")
    if action not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    if environment == "staging" and budget_caps(action):
        budget = min(budget, STAGING_PLAN_CAP)
    return action, budget

