"""Normalize release records at the input boundary.

Also owns identity (duplicate/conflict), replay against the caller's persisted journal,
and the deterministic topological order those two layers need.
"""
import heapq


class JournalError(ValueError):
    pass


def _check_id(value):
    """Accept any non-empty str as an ID, without trimming: what the caller sends is its identity.
    One condition, so every place IDs appear (record, dependency, applied) behaves identically."""
    return isinstance(value, str) and bool(value)


def _check_id_list(raw):
    if raw is None:  # missing key; callers substitute the default
        return []
    if not isinstance(raw, list):
        raise JournalError("invalid-change")
    for item in raw:
        if not _check_id(item):
            raise JournalError("invalid-change")
    return list(raw)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        # type(...) is not int, not isinstance: bool is a subclass of int and must stay rejected.
        if (not isinstance(row, dict) or not _check_id(row.get("id"))
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = _check_id_list(row.get("depends_on"))
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        })
    return changes


def read_applied(raw):
    """The persisted release journal supplied by the caller."""
    return _check_id_list(raw)


def collapse(changes):
    """Replay/dedup: an identical record sent twice is one change.

    Equality covers id, component, units and the *set* of dependencies, so reordering
    depends_on does not make a record different. A reused id with any other difference
    cannot be reconciled, so it fails instead of picking one silently.
    """
    unique = {}
    for row in changes:
        signature = (row["id"], row["component"], row["units"], frozenset(row["depends_on"]))
        seen = unique.get(row["id"])
        if seen is None:
            unique[row["id"]] = row
        elif (seen["id"], seen["component"], seen["units"], frozenset(seen["depends_on"])) != signature:
            # Note the hyphen: the SPEC code is "conflicting-change" (not "conflicting change").
            raise JournalError("conflicting-change")
    return unique


def topological(unique):
    """Deterministic topological order of *all* changes: the lexicographically smallest
    currently eligible ID goes next.

    Cycle detection covers the whole graph, applied entries included: already applied work
    is still part of the release history, and a cycle there means the journal itself is
    contradictory, not merely "nothing left to schedule".
    """
    indegree = {change_id: 0 for change_id in unique}
    dependents = {change_id: [] for change_id in unique}
    for change_id, row in unique.items():
        for dep in set(row["depends_on"]):
            if dep not in unique:
                raise JournalError("unknown-dependency")
            if dep == change_id:
                raise JournalError("dependency-cycle")
            dependents[dep].append(change_id)
            indegree[change_id] += 1

    ready = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for nxt in dependents[current]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(unique):
        raise JournalError("dependency-cycle")
    return order


def replay(unique, applied):
    """Resolve applied IDs and attach them to the change set."""
    for change_id in applied:
        if change_id not in unique:
            raise JournalError("unknown-dependency")
    return set(applied)

