"""Compose policy and journal data into a plan."""
from journal import JournalError, collapse, read_applied, read_changes, replay, topological
from policy import PolicyError, limit_for, validate


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action = validate(request)
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied_ids = read_applied(request.get("applied"))
        unique = collapse(changes)
        # The full order is computed before any filtering so that a cycle anywhere fails,
        # including one that only involves already applied changes.
        order = topological(unique)
        applied = replay(unique, applied_ids)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if action == "rollback":
        # Reverse of the full deterministic order, restricted to applied changes. Budget is
        # validated above but deliberately does not cap a rollback.
        emitted = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Removing nodes from a valid topological order leaves the rest valid: applied
        # changes satisfy their dependencies and consume no new budget.
        emitted = [change_id for change_id in order if change_id not in applied]

    units = sum(unique[change_id]["units"] for change_id in emitted)
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

