"""Compose policy and journal data into a plan."""
from journal import (JournalError, collapse, read_applied, read_changes, read_retain, replay,
                     rollback_retained, topological)
from policy import PolicyError, limit_for, validate


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # G2-1: the production freeze lives inside `validate`, so it fires before budget,
        # change, journal or graph validation - a frozen request with a malformed graph must
        # still answer `production-frozen`, never a graph error or partial actions.
        action = validate(request)
        budget = limit_for(request)  # already min(request, STAGING_PLAN_CAP) for staging
        changes = read_changes(request.get("changes"))
        applied_ids = read_applied(request.get("applied"))
        unique = collapse(changes)
        # The full order is computed before any filtering so that a cycle anywhere fails,
        # including one that only involves already applied changes, and so a rollback's
        # reverse order is well defined before retain is considered.
        order = topological(unique)
        applied = replay(unique, applied_ids)
        # Retention "applies only to rollback": a plan neither consults nor validates this
        # rollback-only field, so a stray or malformed `retain` cannot change a plan. For
        # rollback, `invalid-retain` is raised after replay because "already applied" is only
        # known once `applied` is resolved, and after `topological` so graph errors keep
        # their G1 precedence.
        retain = []
        if action == "rollback":
            retain = read_retain(request.get("retain"))
            for change_id in retain:
                if change_id not in applied:
                    raise JournalError("invalid-retain")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if action == "rollback":
        # Reverse of the full deterministic order, restricted to applied changes. Budget is
        # validated above but deliberately does not cap a rollback. G2-3 then removes the
        # retained closure (retain + their applied transitive dependencies); everything else
        # keeps the G1 reverse order. A retained change is by definition applied, so the
        # remaining sequence is still "every other applied ID in reverse order".
        keep = rollback_retained(unique, applied, retain)
        emitted = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in keep]
    else:
        # Removing nodes from a valid topological order leaves the rest valid: applied
        # changes satisfy their dependencies and consume no new budget.
        emitted = [change_id for change_id in order if change_id not in applied]

    units = sum(unique[change_id]["units"] for change_id in emitted)
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

