"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_str(value):
    return isinstance(value, str) and value != ""


def _string_list(value):
    """Validate an optional ID list: default empty, else array of strings.

    Shared by `depends_on` and `applied` because SPEC requires identical
    malformed-input handling (`invalid-change`) for both.
    """
    if value is None:
        return []
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    out = []
    for item in value:
        if not _is_str(item):
            raise JournalError("invalid-change")
        out.append(item)
    return out


def read_request(request):
    """Validate the request envelope and return its raw pieces.

    Only shape is checked here; `environment`/`action`/`budget` belong to policy.
    """
    if not isinstance(request, dict):
        raise JournalError("invalid-request")
    return request


def read_changes(records, applied=None):
    """Normalize `changes` and the persisted `applied` journal.

    Returns (changes, applied_set): the records in the order first seen, then
    the deduplicated applied IDs. Identity, dedup and replay checks live here so
    planner only ever sees a canonical, non-conflicting view.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    applied_ids = _string_list(applied)
    changes = []
    by_id = {}
    for row in records:
        if (not isinstance(row, dict) or not _is_str(row.get("id"))
                or not _is_str(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = _string_list(row.get("depends_on"))
        record = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        }
        known = by_id.get(record["id"])
        if known is None:
            by_id[record["id"]] = record
            changes.append(record)
            continue
        # Equality covers id, component, units and the *set* of dependencies,
        # so a duplicate that lists the same deps in another order collapses.
        if (known["component"] != record["component"]
                or known["units"] != record["units"]
                or set(known["depends_on"]) != set(record["depends_on"])):
            raise JournalError("conflicting-change")

    known_ids = set(by_id)
    for record in changes:
        for dep in record["depends_on"]:
            # A dependency must name an existing change; self-deps are allowed
            # through here so the planner can report them as a cycle.
            if dep not in known_ids:
                raise JournalError("unknown-dependency")
    unknown_applied = applied_ids and [i for i in applied_ids if i not in known_ids]
    if unknown_applied:
        raise JournalError("unknown-dependency")
    return changes, set(applied_ids)

