    for row in changes:
        deps = set(row["depends_on"])
        blockers[row["id"]] = len(deps)
        for dep in deps:
            dependents[dep].append(row["id"])

    ready = [cid for cid, count in blockers.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependant in dependents[current]:
            blockers[dependant] -= 1
            if blockers[dependant] == 0:
                heapq.heappush(ready, dependant)
    if len(order) != len(changes):
