    keep = set()
    stack = [cid for cid in retained if cid in applied]
    while stack:
        current = stack.pop()
        if current in keep:
            continue
        keep.add(current)
        for dep in deps_by_id[current]:
            if dep in applied and dep not in keep:
                stack.append(dep)
    return keep


